
import { useState } from 'react';
import { Link, useLocation } from 'react-router-dom';

interface GlobalHeaderProps {
  showBanner?: boolean;
  showSearch?: boolean;
}

const navItems = [
  { label: '総合トップ', to: '/' },
  { label: 'ショッピング', to: '/shop' },
  { label: '中古パーツ', to: '/used-parts' },
  { label: '車種選び', to: '/vehicle-select' },
  { label: 'ショップNAVI', to: '/shop-navi' },
  { label: 'メディア', to: '/media' },
  { label: 'サービス', to: '/services' },
  { label: 'コミュニティ', to: '/community' },
  { label: 'イベント', to: '/events' },
  { label: 'ご利用案内', to: '/guide' },
];

export default function GlobalHeader({ showBanner = true, showSearch = true }: GlobalHeaderProps) {
  const location = useLocation();
  const currentPath = location.pathname;
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  const isActive = (to: string) => {
    if (to === '/') return currentPath === '/';
    return currentPath.startsWith(to);
  };

  return (
    <>
      {/* 最上部バナー帯 */}
      {showBanner && (
        <div className="flex flex-col sm:flex-row">
          <div className="flex-1 bg-yellow-400 text-black py-1.5 sm:py-2 px-4 text-center font-bold text-xs sm:text-sm">
            5,500円以上で送料無料！
          </div>
          <div className="flex-1 bg-red-600 text-white py-1.5 sm:py-2 px-4 text-center font-bold text-xs sm:text-sm">
            数量限定シークレットセール開催中
          </div>
        </div>
      )}

      {/* グローバルナビゲーション */}
      <nav className="bg-gray-800 text-white">
        <div className="flex items-center justify-between px-4 sm:px-6 py-3">
          {/* モバイルメニューボタン */}
          <button
            className="lg:hidden text-white p-1"
            onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
          >
            <i className={`ri-${mobileMenuOpen ? 'close' : 'menu'}-line text-2xl`}></i>
          </button>

          {/* デスクトップナビゲーション */}
          <div className="hidden lg:flex gap-4 xl:gap-6 text-sm">
            {navItems.map((item) => (
              <Link
                key={item.to}
                to={item.to}
                className={`whitespace-nowrap cursor-pointer ${
                  isActive(item.to)
                    ? 'text-red-400 font-bold'
                    : 'hover:text-red-500'
                }`}
              >
                {item.label}
              </Link>
            ))}
          </div>

          {/* ログイン/新規登録 */}
          <div className="flex gap-2 sm:gap-3 text-xs sm:text-sm">
            <a href="#" className="hover:text-red-500 whitespace-nowrap cursor-pointer">ログイン</a>
            <span className="hidden sm:inline">/</span>
            <a href="#" className="hover:text-red-500 whitespace-nowrap cursor-pointer hidden sm:inline">新規会員登録</a>
          </div>
        </div>

        {/* モバイルメニュー */}
        {mobileMenuOpen && (
          <div className="lg:hidden bg-gray-700 px-4 py-3 border-t border-gray-600">
            <div className="grid grid-cols-2 gap-2">
              {navItems.map((item) => (
                <Link
                  key={item.to}
                  to={item.to}
                  onClick={() => setMobileMenuOpen(false)}
                  className={`py-2 px-3 rounded text-sm ${
                    isActive(item.to)
                      ? 'bg-red-600 text-white font-bold'
                      : 'bg-gray-600 hover:bg-gray-500'
                  }`}
                >
                  {item.label}
                </Link>
              ))}
            </div>
          </div>
        )}
      </nav>

      {/* ヘッダー */}
      {showSearch && (
        <header className="bg-white border-b border-gray-200 py-3 sm:py-4 px-4 sm:px-6">
          <div className="flex flex-col sm:flex-row items-center justify-between max-w-[1400px] mx-auto gap-3 sm:gap-0">
            {/* ロゴ */}
            <Link to="/" className="flex flex-col items-center sm:items-start cursor-pointer">
              <img
                src="https://static.readdy.ai/image/9cccc7697d198734aa718bd2a70664c9/288e4e86ff9691b6f96385bebb66c1e9.png"
                alt="AutoGarage"
                className="h-8 sm:h-12 mb-1"
              />
              <p className="text-xs text-gray-500 hidden sm:block">自動車用品・パーツ・中古部品の総合通販サイト</p>
            </Link>

            {/* 検索バー */}
            <div className="w-full sm:flex-1 sm:mx-8 sm:max-w-2xl order-last sm:order-none">
              <div className="flex">
                <input
                  type="text"
                  placeholder="商品名、品番、車種名で検索"
                  className="flex-1 border border-gray-300 px-3 sm:px-4 py-2 sm:py-3 text-sm focus:outline-none focus:border-red-500 cursor-text"
                />
                <button className="bg-red-600 text-white px-4 sm:px-8 py-2 sm:py-3 font-bold hover:bg-red-700 whitespace-nowrap cursor-pointer text-sm sm:text-base">
                  検索
                </button>
              </div>
            </div>

            {/* アイコン群 */}
            <div className="flex gap-4 sm:gap-6 items-center">
              <Link to="/cart" className="flex flex-col items-center cursor-pointer hover:opacity-70">
                <i className="ri-shopping-cart-line text-xl sm:text-2xl text-gray-700"></i>
                <span className="text-xs text-gray-600 mt-0.5 sm:mt-1 hidden sm:block">カート</span>
              </Link>
              <div className="flex flex-col items-center cursor-pointer hover:opacity-70">
                <i className="ri-heart-line text-xl sm:text-2xl text-gray-700"></i>
                <span className="text-xs text-gray-600 mt-0.5 sm:mt-1 hidden sm:block">お気に入り</span>
              </div>
              <div className="flex flex-col items-center cursor-pointer hover:opacity-70 hidden sm:flex">
                <i className="ri-history-line text-xl sm:text-2xl text-gray-700"></i>
                <span className="text-xs text-gray-600 mt-0.5 sm:mt-1">履歴</span>
              </div>
              <div className="flex flex-col items-center cursor-pointer hover:opacity-70 hidden sm:flex">
                <i className="ri-store-line text-xl sm:text-2xl text-gray-700"></i>
                <span className="text-xs text-gray-600 mt-0.5 sm:mt-1">業販</span>
              </div>
            </div>
          </div>
        </header>
      )}
    </>
  );
}
